import assert from 'node:assert/strict';
import { Queue } from '../src/queue.js';

test('a new queue has size zero', () => {
  const queue = new Queue();

  assert.equal(queue.size, 0);
});

test('enqueue increases size and dequeue returns items in FIFO order', () => {
  const queue = new Queue();

  queue.enqueue('first');
  assert.equal(queue.size, 1);
  queue.enqueue('second');
  assert.equal(queue.size, 2);

  assert.equal(queue.dequeue(), 'first');
  assert.equal(queue.size, 1);
  assert.equal(queue.dequeue(), 'second');
  assert.equal(queue.size, 0);
});

test('dequeue on an empty queue returns undefined and keeps size zero', () => {
  const queue = new Queue();

  assert.equal(queue.dequeue(), undefined);
  assert.equal(queue.dequeue(), undefined);
  assert.equal(queue.size, 0);
});

test('a drained queue returns undefined and can be reused', () => {
  const queue = new Queue();

  queue.enqueue('first');
  assert.equal(queue.dequeue(), 'first');
  assert.equal(queue.dequeue(), undefined);
  assert.equal(queue.size, 0);

  queue.enqueue('second');
  assert.equal(queue.size, 1);
  assert.equal(queue.dequeue(), 'second');
  assert.equal(queue.size, 0);
});

test('queued values retain their identity, including undefined and falsy values', () => {
  const queue = new Queue();
  const object = { value: 1 };
  const values = [undefined, null, false, 0, '', object];

  for (const value of values) {
    queue.enqueue(value);
  }
  assert.equal(queue.size, values.length);

  for (const [index, value] of values.entries()) {
    assert.equal(queue.dequeue(), value);
    assert.equal(queue.size, values.length - index - 1);
  }
});
